{
  "root": "main_stack",
  "state": {
    "productData": [
      {
        "product": "A",
        "salesUnits": 1200,
        "profitMargin": 0.25
      },
      {
        "product": "B",
        "salesUnits": 800,
        "profitMargin": 0.30
      },
      {
        "product": "C",
        "salesUnits": 1500,
        "profitMargin": 0.20
      },
      {
        "product": "D",
        "salesUnits": 950,
        "profitMargin": 0.28
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_overview",
        "intro_text",
        "title_data",
        "product_table",
        "title_insights",
        "insights_stack"
      ]
    },
    "title_overview": {
      "type": "Text",
      "props": {
        "text": "Product Performance Overview",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This analysis provides a snapshot of four products (A, B, C, D), examining their sales performance in units and associated profit margins. The goal is to visualize the relationship between these two metrics and identify the product with the strongest profit margin."
      },
      "children": []
    },
    "title_data": {
      "type": "Text",
      "props": {
        "text": "Sales Units vs. Profit Margin Data",
        "variant": "h2"
      },
      "children": []
    },
    "product_table": {
      "type": "Table",
      "props": {
        "statePath": "/productData",
        "columns": [
          {
            "key": "product",
            "label": "Product"
          },
          {
            "key": "salesUnits",
            "label": "Sales Units"
          },
          {
            "key": "profitMargin",
            "label": "Profit Margin"
          }
        ],
        "domain": "comparison",
        "preferredPresentation": "cards",
        "primaryColumn": "product",
        "highlightColumns": [
          "profitMargin"
        ],
        "numericColumns": [
          "salesUnits",
          "profitMargin"
        ]
      },
      "children": []
    },
    "title_insights": {
      "type": "Text",
      "props": {
        "text": "Key Insights",
        "variant": "h2"
      },
      "children": []
    },
    "insights_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "insight_1",
        "insight_2",
        "insight_3"
      ]
    },
    "insight_1": {
      "type": "Text",
      "props": {
        "text": "Highest Profit Margin: Product B stands out with the highest profit margin of 30%, despite having the second-lowest sales units."
      },
      "children": []
    },
    "insight_2": {
      "type": "Text",
      "props": {
        "text": "Sales Volume: Product C has the highest sales units at 1500, but its profit margin is the lowest at 20%."
      },
      "children": []
    },
    "insight_3": {
      "type": "Text",
      "props": {
        "text": "Balanced Performance: Product D shows a good balance, with respectable sales units (950) and the second-highest profit margin (28%)."
      },
      "children": []
    }
  }
}
